918	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
919	        const detector = new (BD as any)({ formats: ["qr_code"] });
920	
921	        stopBarcodeDetector = () => {
922	          if (rafId !== null) cancelAnimationFrame(rafId);
923	          stream?.getTracks().forEach((t) => t.stop());
924	          try { video?.remove(); } catch { /* ignore */ }
925	        };
926	
927	        setCameraActive(true);
928	        setCameraStarting(false);
929	
930	        let detecting = false;
