947	                // Permite que o operador mova a câmera antes de tentar de novo.
948	                pauseUntil = Date.now() + 2500;
949	              }
950	            } catch { /* frame fail normal */ }
951	            detecting = false;
952	          }
953	          if (!cancelled) rafId = requestAnimationFrame(loop);
954	        };
955	        rafId = requestAnimationFrame(loop);
956	        return true;
957	
958	      } catch (err) {
959	        stream?.getTracks().forEach((t) => t.stop());
960	        try { video?.remove(); } catch { /* ignore */ }
