967	    // SEM qrbox = lib analisa o frame inteiro. Com qrbox ela corta a área
968	    // → se QR não está exatamente centrado = missed.
969	    const tryHtml5Qrcode = async (): Promise<boolean> => {
970	      await transitionLockRef.current.catch(() => undefined);
971	      if (cancelled) return false;
972	
973	      const el = await waitForElement();
974	      if (!el || cancelled) {
975	        if (!cancelled) setCameraError("Não foi possível inicializar o leitor.");
