1	/**
2	 * Dashboard de containers abertos — visão operacional do estoque parcialmente consumido.
3	 *
4	 * Lista etiquetas com status='aberta' (operador retirou avulso, sobrou saldo dentro).
5	 * Cada linha mostra: produto, saldo/capacidade, % consumido, dias desde abertura,
6	 * loja onde está, e atalho pra timeline da etiqueta.
7	 *
8	 * Útil pra: identificar containers parados, planejar consumo de produtos abertos
9	 * (FEFO interno), evitar perdas por validade após abertura.
10	 */
11	import { useEffect, useMemo, useState } from "react";
12	import { Link } from "react-router-dom";
